begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table document_fixture(asset uuid,other_asset uuid,submission uuid,item uuid,revision uuid,new_revision uuid,evidence uuid);grant select,insert,update on document_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99510000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Document evidence course','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','99520000-0000-4000-8000-000000000001','99510000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Document response','Explain',10,'61000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000001','99520000-0000-4000-8000-000000000002','99510000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Other document response','Explain',10,'61000000-0000-4000-8000-000000000001');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
insert into document_fixture(asset)values((internal.submission_document_command('stage','99520000-0000-4000-8000-000000000001',null,'{"name":"إجابة.txt","contentType":"text/plain","byteSize":10,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','document-stage',repeat('a',64),'document-test')->>'id')::uuid);
select throws_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture))),'document-staged-work',repeat('b',64),'document-test')$$,'42501',null,'staged documents cannot become immutable submitted work');
select throws_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,'{"responseKind":"FILE","content":"","assetIds":[null]}','document-null-work',repeat('b',64),'document-test')$$,'22023',null,'null document identifiers rejected');
select throws_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,'{"responseKind":"FILE","content":"","assetIds":{}}','document-object-work',repeat('b',64),'document-test')$$,'22023',null,'malformed document array rejected');
select internal.submission_document_command('finalize','99520000-0000-4000-8000-000000000001',(select asset from document_fixture),jsonb_build_object('sha256',repeat('a',64),'byteSize',10),'document-finalize',repeat('c',64),'document-test')is not null as finalized;
select lives_ok($$select internal.submission_document_command('finalize','99520000-0000-4000-8000-000000000001',(select asset from document_fixture),jsonb_build_object('sha256',repeat('a',64),'byteSize',10),'document-finalize-new-key',repeat('c',64),'document-test')$$,'new finalize key reconciles semantic availability without duplicating transitions');
select throws_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture),(select asset from document_fixture))),'document-duplicate',repeat('d',64),'document-test')$$,'22023',null,'duplicate submitted asset selection rejected');
select throws_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000002',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture))),'document-other-assessment',repeat('d',64),'document-test')$$,'42501',null,'own asset from another assessment denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select throws_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture))),'document-other-owner',repeat('d',64),'document-test')$$,'42501',null,'peer asset cannot become own submission');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select internal.submission_work_command('draft','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture)),'expectedRevision',0),'document-draft',repeat('e',64),'document-test')is not null as drafted;
select is(internal.read_submission_work_draft('99520000-0000-4000-8000-000000000001')->>'responseKind','FILE','server draft restores file source kind');
select is(jsonb_array_length(internal.read_submission_work_draft('99520000-0000-4000-8000-000000000001')->'artifacts'),1,'server draft restores exact verified manifest');
select lives_ok($$select internal.save_submission_draft('99520000-0000-4000-8000-000000000001','Legacy text working answer',1)$$,'legacy text editor remains compatible with shared FILE draft source');
select is(internal.read_submission_work_draft('99520000-0000-4000-8000-000000000001')->>'responseKind','TEXT','legacy text save resets explicit response kind');
select is(jsonb_array_length(internal.read_submission_work_draft('99520000-0000-4000-8000-000000000001')->'artifacts'),0,'legacy text save clears unrelated draft selection');
select internal.submission_work_command('draft','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture)),'expectedRevision',2),'document-draft-again',repeat('e',64),'document-test')is not null as redrafted;
update document_fixture set submission=(internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array(asset)),'document-submit',repeat('f',64),'document-test')->>'id')::uuid;
select lives_ok($$select internal.submission_work_command('submit','99520000-0000-4000-8000-000000000001',null,jsonb_build_object('responseKind','FILE','content','','assetIds',jsonb_build_array((select asset from document_fixture))),'document-submit',repeat('f',64),'document-test')$$,'original submission key reconciles same exact source');
select is(internal.read_submitted_work((select submission from document_fixture))->>'content','','file-only source preserves empty text rather than fabricating an answer');
select is(internal.read_submitted_work((select submission from document_fixture))->>'responseKind','FILE','file-only source remains explicit');
select is(internal.submission_artifact_delivery((select submission from document_fixture),(select asset from document_fixture))->>'id',(select asset::text from document_fixture),'own academic delivery resolves exact submitted artifact');
select throws_ok($$select internal.asset_command('retire',(select asset from document_fixture),'{"reason":"Wrong purpose route","confirmRetirement":true}','document-generic-retire',repeat('a',64),'document-test')$$,'42501',null,'generic personal asset route cannot retire academic asset');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_submitted_work((select submission from document_fixture))$$,'42501',null,'parent generic submitted work denied');
select throws_ok($$select internal.submission_artifact_delivery((select submission from document_fixture),(select asset from document_fixture))$$,'42501',null,'parent generic submitted bytes denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare result uuid;begin result:=internal.release_marking(internal.mark_submission((select submission from document_fixture),6,'Teacher checked actual document',1,0,true),1,true);update document_fixture set evidence=(select evidence_id from app.result_revisions where id=result);end$$;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update document_fixture set item=(internal.portfolio_command('create',null,jsonb_build_object('sourceModel','numeric','evidenceId',evidence,'title','Selected document','reflection','I checked the source','assetIds',jsonb_build_array(asset)),'document-portfolio',repeat('b',64),'document-test')->>'id')::uuid;
reset role;update document_fixture set revision=(select revision_id from app.portfolio_current where item_id=document_fixture.item);set local role cuevo_api;
select is(internal.read_portfolio_source_work((select item from document_fixture),(select revision from document_fixture))->'source'->>'kind','FILE','selected portfolio uses actual file source');
select is(jsonb_array_length(internal.read_portfolio_source_work((select item from document_fixture),(select revision from document_fixture))->'source'->'artifacts'),1,'selected portfolio freezes exact manifest');
select throws_ok($$select internal.portfolio_command('reflection',(select item from document_fixture),'{"title":"No actual file","reflection":"Invalid empty selection","expectedRevision":1,"assetIds":[]}','document-empty-selection',repeat('c',64),'document-test')$$,'22023',null,'FILE reflection cannot omit every actual artifact');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.portfolio_command('review',(select item from document_fixture),'{"expectedRevision":1,"feedback":"Exact documents reviewed","featured":false,"parentVisible":true,"confirmParentApproval":true,"confirmSourceReview":true}','document-review',repeat('d',64),'document-test')is not null as reviewed;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select lives_ok($$select internal.portfolio_artifact_delivery((select item from document_fixture),(select revision from document_fixture),(select asset from document_fixture))$$,'current parent receives exact explicitly approved selected document');
select throws_ok($$select internal.portfolio_artifact_delivery((select item from document_fixture),(select revision from document_fixture),'99520000-0000-4000-8000-000000000001')$$,'42501',null,'nonselected asset substitution denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select internal.portfolio_command('reflection',(select item from document_fixture),'{"title":"New private reflection","reflection":"Needs review","expectedRevision":1}','document-new-reflection',repeat('e',64),'document-test')is not null as reflected;
reset role;update document_fixture set new_revision=(select revision_id from app.portfolio_current where item_id=document_fixture.item);set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.portfolio_artifact_delivery((select item from document_fixture),(select new_revision from document_fixture),(select asset from document_fixture))$$,'42501',null,'new reflection/artifact manifest cannot inherit approval');
select lives_ok($$select internal.portfolio_artifact_delivery((select item from document_fixture),(select revision from document_fixture),(select asset from document_fixture))$$,'approved prior manifest remains pinned while current reflection private');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select internal.submission_document_command('retire','99520000-0000-4000-8000-000000000001',(select asset from document_fixture),'{"reason":"Student retires document with explicit intent","confirmRetirement":true}','document-retire',repeat('f',64),'document-test')is not null as retired;
select is(internal.read_submitted_work((select submission from document_fixture))->'artifacts'->0->>'state','RETIRED','retired source metadata remains in immutable work');
select throws_ok($$select internal.submission_artifact_delivery((select submission from document_fixture),(select asset from document_fixture))$$,'42501',null,'retirement removes academic byte delivery');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.portfolio_artifact_delivery((select item from document_fixture),(select revision from document_fixture),(select asset from document_fixture))$$,'42501',null,'retirement removes approved parent byte delivery');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.portfolio_command('review',(select item from document_fixture),'{"expectedRevision":2,"feedback":"Unavailable document cannot be shared","featured":false,"parentVisible":true,"confirmParentApproval":true,"confirmSourceReview":true}','document-unavailable-review',repeat('a',64),'document-test')$$,'22023',null,'review cannot approve a retired selected artifact');
select ok(not has_table_privilege('cuevo_api','app.submission_artifacts','select'),'raw submission manifest table grant stays denied');select ok(not has_table_privilege('authenticated','app.portfolio_artifacts','select'),'browser selected artifact table stays private');select ok(not has_function_privilege('authenticated','internal.submission_artifact_delivery(uuid,uuid)','execute'),'browser role cannot invoke academic delivery helper');
reset role;
select is((select count(*)from app.submission_artifacts where submission_id=(select submission from document_fixture)),1::bigint,'submission/replay/retirement retain one immutable manifest');
select is((select count(*)from internal.audit_events where entity_id=(select asset from document_fixture)and action='submission.document.finalize'),1::bigint,'new finalize keys do not duplicate semantic availability audit');
select throws_ok($$update app.submission_artifacts set sequence=2 where submission_id=(select submission from document_fixture)$$,'55000',null,'submitted manifest cannot be rewritten');select throws_ok($$truncate app.portfolio_artifacts$$,'55000',null,'selected manifest history cannot be truncated');
select*from finish();rollback;

